const TRAVANCORE_INFO={id:"travancore-kingdom",name:"Kingdom of Travancore",motto:"Dharmo Asmat Kuladaivatam (Dharma is our Family Deity)",capital:"Padmanabhapuram (until 1795) / Thiruvananthapuram",period:"1729 – 1949 CE",stateRegion:"Southern Kerala & Kanyakumari (India)",dynasty:"Venad / Kulasekhara Dynasty",deity:"Lord Padmanabha (Sree Padmanabhaswamy Temple)",quickStats:[{label:"Founded Year",value:"1729 CE",icon:"👑"},{label:"Naval Victory",value:"Colachel (1741)",icon:"⚓"},{label:"State Deity",value:"Lord Padmanabha",icon:"🛕"},{label:"Literacy Reform",value:"Pioneer in India",icon:"📜"},{label:"Temple Entry",value:"1936 Proclamation",icon:"⚖️"},{label:"Accession",value:"1949 to India",icon:"🇮🇳"}]},TIMELINE_DATA=[{year:"1729 CE",title:"Establishment of Modern Travancore",description:"Anizham Thirunal Marthanda Varma ascends the throne of Venad and consolidates smaller principalities to establish Travancore."},{year:"1741 CE",title:"Battle of Colachel",description:"Travancore forces decisively defeat the Dutch East India Company, permanently ending European colonial naval dominance in Kerala."},{year:"1750 CE",title:"Thripadidanam",description:"Marthanda Varma surrenders his kingdom to Sree Padmanabhaswamy, ruling as a servant of the deity (Padmanabhadasa)."},{year:"1789 CE",title:"Defense against Tipu Sultan",description:"Dharma Raja successfully defends Travancore against the northern invasion forces of Mysore."},{year:"1813–1846 CE",title:"Golden Era of Music & Arts",description:"Swathi Thirunal Rama Varma patrons Carnatic and Hindustani music, composing over 400 classical ragas."},{year:"1936 CE",title:"Temple Entry Proclamation",description:"Sree Chithira Thirunal Balarama Varma issues the historic decree granting temple entry rights to all Hindus regardless of caste."},{year:"1949 CE",title:"Accession to Union of India",description:"Travancore merges with Cochin to form Travancore-Cochin state, later integrating into the state of Kerala."}],RULERS_DATA=[{name:"Marthanda Varma (1729–1758)",role:"Founder & Military Strategist",achievements:"Unified southern Kerala, defeated the Dutch Navy at Colachel, instituted Thripadidanam, and constructed the grand Padmanabhapuram Palace."},{name:"Dharma Raja (1758–1798)",role:"Protector & Patron of Arts",achievements:"Shifted the capital to Thiruvananthapuram, provided refuge to artists fleeing Tipu Sultan's invasion, and strengthened state fortifications."},{name:"Swathi Thirunal Rama Varma (1829–1846)",role:"Royal Musician & Scholar King",achievements:"Renowned composer in Carnatic and Hindustani classical music; established the Trivandrum Observatory, modern civil courts, and English education."},{name:"Chithira Thirunal Balarama Varma (1931–1949)",role:"Last Ruling Maharaja",achievements:"Proclaimed the Temple Entry Proclamation (1936), founded the University of Kerala (1937), and promoted industrialization (FACT, Travancore Titanium)."}],CONTRIBUTIONS_DATA={overview:"The Kingdom of Travancore was one of the most progressive princely states in British India, pioneering free primary education, universal healthcare, and landmark social justice initiatives.",militaryNaval:"Famous for the historic Battle of Colachel (1741), where Travancore became the first Asian power to crush a major European naval empire (Dutch East India Company).",architecture:"Architectural marvels include the majestic Sree Padmanabhaswamy Temple (Gopuram & 1000-pillared hall), Padmanabhapuram Wooden Palace, and Kowdiar Palace.",educationSocial:"Introduced free primary education for all children in 1817 under Rani Gouri Parvathi Bayi and established the University of Travancore (1937).",musicCulture:"Swathi Thirunal elevated Kathakali, Mohiniyattam, and Carnatic music, producing masterpieces performed across India to this day."},GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Sree_Padmanabhaswamy_Temple_Trivandrum.jpg/800px-Sree_Padmanabhaswamy_Temple_Trivandrum.jpg",caption:"Sree Padmanabhaswamy Temple — Spiritual heart of the Travancore Kingdom",category:"Architecture"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Padmanabhapuram_Palace_front_view.jpg/800px-Padmanabhapuram_Palace_front_view.jpg",caption:"Padmanabhapuram Wooden Palace — Capital of Travancore until 1795",category:"Heritage"}],REFERENCES=[{text:"Menon, A. Sreedhara (2007). A Survey of Kerala History. DC Books.",link:"#"},{text:"Nagam Aiya, V. (1906). The Travancore State Manual. Travancore Government Press.",link:"#"},{text:"Pillai, Elamkulam Kunjan (1970). Studies in Kerala History. National Book Stall.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={TRAVANCORE_INFO:TRAVANCORE_INFO,TIMELINE_DATA:TIMELINE_DATA,RULERS_DATA:RULERS_DATA,CONTRIBUTIONS_DATA:CONTRIBUTIONS_DATA,GALLERY_IMAGES:GALLERY_IMAGES,REFERENCES:REFERENCES});